// e.App
// e.Collection
return e.Next()
})
// fires only for "users" and "articles" collections
app.OnCollectionUpdate("users", "articles").BindFunc(func(e *core.CollectionEvent) error {
// e.App
// e.Collection
return e.Next()
})
if err := app.Start(); err != nil {
log.Fatal(err)
}
}`

